#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STACK 64

int main(int argc, char **argv) {
    long stack[MAX_STACK];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        /* operator? */
        if (strlen(arg) == 1 && (*arg == '+' || *arg == '-' || *arg == '*' || *arg == '/')) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack[--top];
            long a = stack[--top];
            long res = 0;
            switch (*arg) {
                case '+': res = a + b; break;
                case '-': res = a - b; break;
                case '*': res = a * b; break;
                case '/':
                    if (b == 0) { puts("ERROR"); return 0; }
                    res = a / b; break;
            }
            stack[top++] = res;
        } else {
            char *endptr;
            long val = strtol(arg, &endptr, 10);
            if (endptr == arg || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }

    if (top != 1) {
        puts("ERROR");
        return 0;
    }

    printf("%ld\n", stack[0]);
    return 0;
}
